def cost_venue1(guests):
    return 200 + 5 * guests

def cost_venue2(guests):
    return 25 * guests

def find_break_even(venue1, venue2):
    guests = 0
    while venue1(guests) <= venue2(guests):
        guests += 1
    return guests

break_even = find_break_even(cost_venue1, cost_venue2)
